addedToArea.action:
var hybrids = ["human_thrall", "human_thrall2", "paramedic"];
var target = null;
for(hybrid in hybrids) {
    var object = area.getObject(hybrid);
    if(object != null) {
        var target = object;
        Movement.seek(this, object, 4, true)
    }
}

over.action:
var object = target
var maxHealth = object.info.xml.get("health");
if(Std.parseInt(object.health) + 10 > Std.parseInt(maxHealth)) {
object.health = maxHealth;
} else {
object.health = Std.parseInt(object.health) + 10;
}
